using System;

namespace Net5_CSharp10.CSharp7_3.BackingFieldAttributes
{
    [Serializable]
    public class Model
    {
        // An auto-property's backing field is generated by the compiler and has
        // an unspeakable name, so before C# 7.3 there was no way to put an
        // attribute on it. The field: target now reaches it.
        [field: NonSerialized]
        public string Cache { get; set; }

        public string Name { get; set; }

        public Model(string name)
        {
            Name = name;
            Cache = string.Empty;
        }
    }
}
